namespace bo3z::codex
{
	struct Chapter { int book; std::string_view title, image; std::vector<std::string_view> paras; };
	inline constexpr std::array<std::string_view, 15> kBooks{ "The Curse of Alduin", "The Summoner's Path", "The Battle-mage's Path", "The Alchemist's Path", "The Spellsword's Path", "The Broken Words: Riverwood", "The Broken Words: Whiterun", "The Broken Words: Solitude", "The Broken Words: Windhelm", "The Broken Words: Markarth", "The Broken Words: Riften", "The Broken Words: Falkreath", "The Broken Words: Morthal", "The Broken Words: Dawnstar", "The Broken Words: Winterhold" };  // 0 the lore, 1-4 the class guides (Summoner, Destruction, Ranger, Spellsword), 5+ a freed city's page (kTowns order)
	inline const std::vector<Chapter> kChapters{
		{ 0, "The Greybeard's Account", "sigil", { "Written at High Hrothgar by a Greybeard who broke his silence, for whoever lived through Helgen" } },
		{ 0, "I. What Happened", "helgen", { "When Alduin rose over Helgen, he shouted three Words into the earth: <b>SLEN TIID VO</b> - Flesh, Time, Undo. It is the shout that raises the dead.", "His mist also covers the door of <b>Sovngarde</b>, so the dead of Skyrim cannot pass on. They lie restless in the ground. By day they sleep. When the sun goes down, they rise." } },
		{ 0, "II. The Dead", "graves", { "Each night the dead come in <b>waves</b>, more of them and harder to kill as the nights go on. They claw up out of open ground - roads and fields, never inside a house - and come at you from every side. Dawn comes only when the last wave falls.", "The curse's whole host walks with them, each under its own name. Mihail's zombies and the Thriceborn come first with the Rag Draugr, rotten skeletons and plague wolves; then Bonemen, skeleton mages and the necromancers who serve the curse - kill those first, for they raise more; then Hulking Draugr, Draugr Liches, Draman Brutes, Ash Spawn and werewolves; and at the last the Daedra and the Overlords.", "Some nights the noise you make draws a hunter that comes through a portal and pounces. The Curse's champions and great ones step out of portals too - and their names burn gold over their heads." } },
		{ 0, "III. The Echo Altars", "wards", { "Long ago the <b>Tongues</b>, the first masters of the Voice, raised an altar in every hold to hold Alduin's shout back. Every mage who fell in the Dragon War gave a last spell to them, which is why an altar still has spells, bows and gifts to give.", "Alduin's return woke the altars only halfway. Each one is held silent by a <b>Dragon Priest</b>, still bound by his old oath to Alduin." } },
		{ 0, "IV. Waking an Altar", "", { "Stand at an altar and it sets you <b>trials</b>: hold its rune circle, cull the dead in its streets, hold the altar through a night's waves, and pass the trial of your own path. Finish them and its Dragon Priest rises at night. Kill him and the altar wakes.", "A woken altar makes its city a <b>sanctuary</b>: none of the curse's dead rise inside it, by night or by day. Step outside its walls and they find you again." } },
		{ 0, "V. The Dragonborn's Road", "", { "The Curse walks beside your own story; it does not replace it.", "<b>Riverwood's</b> altar, nearest Helgen, wakes first. <b>Whiterun's</b> answers your first dragon soul and gives you a dragon to ride - and its Thu'um, <i>Dragon's Updraft</i>. <b>Solitude's</b> bards give you the <i>Dance of Death</i>.", "Free six cities and each path's <b>secret</b> wakes. Win it and the Greybeards call you to <b>High Hrothgar</b>: your path's <b>wonder</b> waits on its pedestal in the Reliquary beneath the great hall.", "With all four wonders won - alone or with friends - Alduin's three Words wake as <b>dragons</b>: <b>SLEN</b> in the Reach, <b>TIID</b> at Labyrinthian and <b>VO</b> on Mount Anthor. Slay all three, wake every altar, and only his <b>Echo</b> is left, on the summit of the Throat of the World. End it, and the Curse is broken." } },
		{ 0, "VI. The Voices of the Holds", "", { "<b>Whiterun</b>: <i>Dragon's Updraft</i>. A whirlwind lifts you high - and a dragon to carry you.", "<b>Solitude</b>: <i>Dance of Death</i>. The dead near you dance, helpless, and take half again as much harm. Once a wave." } },
		{ 0, "Epilogue", "", { "Every Echo Altar in Skyrim is awake. Alduin's voice lingers only in the wild places now - and in the echo he left on the Throat of the World.", "<i>- written in the silence of High Hrothgar</i>" } },
		{ 1, "The Summoner", "", { "A conjurer of the <b>College of Winterhold</b>. Your summons fight for you - every kill they make is yours: Cursed Essence, progress and trials.", "<b>You start with</b> Conjure Wolf (left hand), Conjure Skeleton in your spellbook, the <b>Radiant Quarterstaff</b> (right hand) and the <b>Summoner Set</b> (a conjurer's robe, hood and boots) (your armor set: Tier I your summons take a fifth less, Tier II one more summon slot, Tier III your summons' kills heal you). Every class sword climbs the same way: Base is the bare sword; Tier I its element wakes on the blade and every light swing sends out an arc slash in its colour that pierces through the dead; Tier II its heavy attacks burst round where they land; Tier III its own power. The <b>Radiant Quarterstaff</b>'s light is white; at Tier III three blades of light circle you and strike the dead that come near." } },
		{ 1, "Your Progress", "@progress", {  } },
		{ 1, "Your Altar", "", { "<b>Your kit</b> - each item with its tier and the price of its next upgrade. Select one to upgrade it.", "<b>The Armory</b> - more summon families open as you free cities: <b>Dwemer</b> at 1, <b>Atronachs</b> at 2, <b>the Wild</b> at 3, <b>Ash</b> at 4, <b>Daedra</b> at 5, <b>the Night</b> at 7, <b>the Wrath</b> at 9. You keep every family you buy.", "<b>Dragon Priests</b> - every Dragon Priest you slay drops <b>3,000 Cursed Essence</b>." } },
		{ 1, "Getting Stronger", "", { "<b>One curve for everything.</b> Every item in your kit climbs Base, <b>Tier I</b> (1.3 times its damage), <b>Tier II</b> (1.7 times), <b>Tier III - Legendary</b> (2.2 times), then <b>Ascends</b> (+0.3 times each). Prices: Tier I 4,000, Tier II 6,000 (needs 2 freed cities), Tier III 8,000 (4 cities), Ascend 10,000 and 2,000 more each time (6 cities); after night 10 every upgrade and Armory price is 3% higher each night. Your class's <b>armor set</b> is in your kit too: it starts at 5% damage reduction and every tier adds 5% (20% at Tier III), with a power of its own at each tier; each Ascend of the set adds 5% to all your damage. As the set climbs it wraps you in an <b>aura</b> of your class's colour: a faint sheen at Tier I, wisps rising off you at Tier II, a full aura at Tier III, burning brighter with each Ascend.", "<b>Summon slots</b> - how many summons you can have out at the same time. You start with <b>2</b>; the Pack Leader Mead adds one and your robes' Tier II one more - <b>4</b> at most. When every slot is full, a new summon replaces your oldest one." } },
		{ 1, "Your Perks", "", { "<b>Pack Leader Mead</b> - one more summon out at a time.", "<b>Grave Fury Wine</b> - your summons deal 25% more damage.", "<b>Bone Burst Brew</b> - a summon of yours that dies explodes, hurting the dead round it.", "Up to <b>five brews</b> at once, 3,000 each. They stay through death; select one you hold at the altar to give it back for half. Your class's brews work only while you play this class (they still count toward the five); the seven brews every class can take are in <i>The Echo Altar</i>." } },
		{ 1, "Your Trial and Wonder", "", { "<b>Pact of the Host</b> (your city trial): let your summons make the kills - 20 on Novice up to 60 on Legendary.", "<b>Soulcaller's Staff</b> (your wonder, a staff): it can't be bought. Once six cities are freed, all four <b>secrets</b> wake - long hidden quests played from altar to altar, never twice in a row in the same city, one at a time (your own class's first). Any class may win and wield any wonder. Listen to the freed altars' whispers. When it is won the Greybeards call: the wonder floats waiting in High Hrothgar's great hall. Hold its cast: its beam tears at the dead along your aim, and each one that dies while you hold it gives the staff its soul (up to eight, counted under your crosshair). Let go and the souls return as spectral wolves that hunt for 20 seconds - one for each soul." } },
		{ 1, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead are the curse's whole host, each under its own name: Mihail's zombies and the Thriceborn walk first with the Rag Draugr, rotten skeletons and plague wolves; then Bonemen, skeleton mages and the necromancers who serve the curse; then Hulking Draugr, Draugr Liches, Draman Brutes, Ash Spawn and werewolves; then the Daedra - Clannfear, Daedroth, Dremora - and at the last the Overlords, the Mythic Liches and the Skeleton Reaper Warlords. Casters keep back and raise more dead - kill them first.", "Some nights the noise you make draws a hunter: a feral nightwalker, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars and the Tablet of Mysteries. After night 10, as the dead grow many, each kill gives a little less. From dusk to dawn a lantern at your belt lights 20 metres round you. At dawn the dead leave their ash where they fell, and in a freed city its people leave an offering at their altar for you each day.", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 1, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for Cursed Essence - each class keeps its own kit and progress), then sections that open one at a time: <b>Your Kit</b> (select an item to upgrade it), <b>the Armory</b> (new items, opened by freed cities), <b>Perks</b>, <b>Your Dragon</b>, the city's <b>Trials</b> and the <b>Whispers</b> of your path's secret.", "<b>Brews</b> (the Perks section): the seven every class can take - <b>Troll's Hide Mead</b> +50 health; <b>Wellspring Draught</b> +50 magicka; <b>Stormrunner Brew</b> you move 15% faster; <b>Bounty Hunter's Ale</b> elites and mini-bosses give twice the Cursed Essence; <b>Last Stand Ale</b> below a quarter of your health you take 25% less; <b>Gilded Tongue Tonic</b> 15% more Cursed Essence from kills; <b>Dragonsblood Cider</b> your shouts recharge 25% faster - and three of your class's own. Up to five at once, 3,000 each, kept through death; select one you hold to give it back for half.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. Its fall ends the night and drops 3,000 Cursed Essence. A freed city is a sanctuary: none of the curse's dead rise inside it. Whiterun gives you a dragon to ride and Dragon's Updraft; Solitude gives you the Dance of Death.", "<b>Every 5th night</b> a great boss walks with the dead - kill it before dawn.", "<b>Waking an altar</b>: Riverwood's altar is open from the first night. Every other city's trials stay locked until that city's own quest is done - Whiterun: <b>Dragon Rising</b>; Solitude: <b>The Wolf Queen Awakened</b>; Windhelm: <b>The White Phial</b>; Markarth: <b>The Forsworn Conspiracy</b>; Riften: <b>The Book of Love</b>; Falkreath: <b>Ill Met By Moonlight</b>; Morthal: <b>Laid to Rest</b>; Dawnstar: <b>Waking Nightmare</b>; Winterhold: the Jarl's <b>Helm of Winterhold</b> (Dungeon Delving)." } },
		{ 1, "The Tablet of Mysteries", "", { "Once a city is freed, an old floating tablet of cracked stone waits in one of the freed cities - on your map and compass. Pay Cursed Essence and it turns: its rings grind round and a <b>donated weapon</b> rises out of its face. Activate the tablet within 12 seconds to take it: it goes straight into your hands (what you held goes back to your pack).", "<b>Price</b>: 1,500 a turn, and 500 more after every turn or repair, back to 1,500 at dawn; after night 10 it is 3% higher each night.", "<b>Used and forgotten</b>: a <b>worn</b> weapon is one tier above your class sword; a <b>battered</b> one (15% of turns - the tablet rings gold) is two tiers above, with fewer uses. Each has limited uses - hits, arrows or casts - shown in its name (62%) and on a bar under your hand cards. Holding it at the tablet, pay a turn's price to <b>mend</b> it to full. At nothing left it breaks; fall and it is lost. You carry one at a time: a new one replaces it.", "<b>The mask</b>: after four to eight turns a Dragon Priest's mask may rise instead - your Cursed Essence comes back and the tablet flies to another freed city. In a party each player turns their own.", "<b>Worn</b>: <b>Stormtalons</b> (claws, 100 uses) - every 3rd hit jumps lightning to 2 more of the dead; a heavy hit stuns the one struck. <b>Gravebell Mace</b> (mace, 100 uses) - every 5th hit tolls it, stunning the dead within 5 m. <b>Riverstone Halberd</b> (halberd, 100 uses) - its hits knock the dead back; a heavy attack splits the ground in a line before you. <b>Rimewick Quarterstaff</b> (quarterstaff, 100 uses) - its spins strike like any staff's; a heavy attack that lands throws the light out as an orb that pulls the dead in, then bursts. <b>Cinderclaws</b> (claws, 100 uses) - every swipe sets the dead burning; a heavy swipe flings a fan of embers. <b>Frostmourn Rapier</b> (rapier, 100 uses) - its thrusts slow everything they touch; a heavy thrust freezes a ring of the dead around you. <b>Silver Reaping Scythe</b> (scythe, 100 uses) - every hit on the dead strikes a quarter harder. <b>Wyrmtooth Scythe</b> (scythe, 100 uses) - its hits make the dead bleed; a heavy sweep bursts teeth out of the ground in an arc ahead.", "<b>Battered</b>: <b>Talons of Woe</b> (claws, 30 uses) - their bleed runs twice as deep in the dead, and each kill heals you a little. <b>Wyrmspine Pike</b> (pike, 30 uses) - its thrusts pierce through 2 more of the dead in a line; a heavy thrust drives a spike of bone up out of the ground ahead. <b>Eclipse Edge</b> (glass pike, 30 uses) - light thrusts alternate the two; a heavy attack calls a 6-second eclipse that blinds and slows the dead. <b>The Wandering Star</b> (wand, 30 uses) - hold its cast and it looses a star every half second, bouncing on through two more of the dead. <b>Bonereaper</b> (scythe, 30 uses) - one kill in four raises the fallen to fight for you for 20 seconds. <b>Bloodmoon Scythe</b> (scythe, 30 uses) - every hit drains a little of the dead's blood into you; a heavy sweep drains everything it touches." } },
		{ 1, "The Road to the Echo", "", { "<b>High Hrothgar's hall</b>: once six cities are free, the four <b>secrets</b> wake - your own class's first, then the others, one at a time. Win one and the Greybeards call you - its <b>wonder</b> floats waiting in High Hrothgar's great hall. Look at it and press Activate or left click to take it up. Every wonder answers to every class: mix and match.", "<b>The three dragons</b>: with all four wonders won (win each secret in turn, or pool them with your party), Alduin's three words wake as dragons - <b>SLEN</b> at the cult's shrine in the Reach, <b>TIID</b> at Labyrinthian, <b>VO</b> on Mount Anthor. Go at night: the dead come first, then the dragon. Each one slain gives a lasting power, and with all three dead your wonders take their <b>Legendary</b> form.", "<b>The Echo of Alduin</b>: last of all, once the three dragons are dead and every Echo Altar is awake, on the summit of the Throat of the World. Slay it and the curse is broken - the nights are only nights again, and High Hrothgar becomes the <b>Hall of the Awakened</b>: Alduin's Bane floats over the fire at the hall's end, and the <b>Endless Flame</b> burning on the centre pillar holds the rest - the First Dragonborn's Regalia, Alduin's Bones for your dragon, the Endless Night and Begin Again (New Game+)." } },
		{ 1, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay) and changes everything - the dead, the elites, the bosses, and your weapons and spells. Novice is very easy, Apprentice normal, Adept hard, Expert very hard, Master extremely hard and Legendary nearly impossible. From Novice to Legendary the dead have <b>0.6x, 1x, 1.4x, 1.9x, 2.6x, 3.5x</b> health and hit <b>0.5x, 1x, 1.4x, 1.9x, 2.6x, 3.5x</b> as hard, and your weapons and spells deal <b>1.5x, 1x, 0.9x, 0.8x, 0.7x, 0.6x</b> damage.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 2, "The Battle-mage", "", { "A battle-mage of the <b>College of Winterhold</b>: a different element in each hand, struck from afar - bolts, beams, storms and runes.", "<b>You start with</b> the <b>Carian Wand</b> (in your right hand - hold its cast and it looses a bolt every half second, fire, lightning and ice in turn; Tier II every 3rd bolt is a great bolt that pierces; Tier III every 3rd also looses a crossing volley; the wand goes steel, stalhrim, glass, ebony, then daedric when Ascended), Ice Spike (left hand), Firebolt in your spellbook, a Destruction tome and the <b>Destruction Set</b> - your armor set (Black Mage Armor's College robes, hood and boots; from Tier I an aura in your class's colour, brighter each tier): Tier I spells cost 10% less, Tier II magicka comes back faster, Tier III spells cost a quarter less. Your magicka starts coming back 1 second after a cast." } },
		{ 2, "Your Progress", "@progress", {  } },
		{ 2, "Your Altar", "", { "<b>Your kit</b> - each element with its tier and the price of its next upgrade: each tier is the next spell of its ladder (Firebolt, Fireball, Incinerate, Immolate).", "<b>The Armory</b> - more elements open as you free cities: <b>Shock</b> at 1, <b>Sun</b> at 3, <b>Walls</b> at 4, <b>Arcane</b> at 5, <b>Storms</b> at 9.", "<b>Dragon Priests</b> - every Dragon Priest you slay drops <b>3,000 Cursed Essence</b>." } },
		{ 2, "Getting Stronger", "", { "<b>One curve for everything.</b> Every item in your kit climbs Base, <b>Tier I</b> (1.3 times its damage), <b>Tier II</b> (1.7 times), <b>Tier III - Legendary</b> (2.2 times), then <b>Ascends</b> (+0.3 times each). Prices: Tier I 4,000, Tier II 6,000 (needs 2 freed cities), Tier III 8,000 (4 cities), Ascend 10,000 and 2,000 more each time (6 cities); after night 10 every upgrade and Armory price is 3% higher each night. Your class's <b>armor set</b> is in your kit too: it starts at 5% damage reduction and every tier adds 5% (20% at Tier III), with a power of its own at each tier; each Ascend of the set adds 5% to all your damage. As the set climbs it wraps you in an <b>aura</b> of your class's colour: a faint sheen at Tier I, wisps rising off you at Tier II, a full aura at Tier III, burning brighter with each Ascend." } },
		{ 2, "Your Perks", "", { "<b>Overflow Tea</b> - every 3rd Destruction spell you cast is free.", "<b>Ember Echo Ale</b> - the dead your Destruction spells kill explode, hurting those round them.", "<b>Mana Font Draught</b> - your magicka refills 40% faster.", "Up to <b>five brews</b> at once, 3,000 each. They stay through death; select one you hold at the altar to give it back for half. Your class's brews work only while you play this class (they still count toward the five); the seven brews every class can take are in <i>The Echo Altar</i>." } },
		{ 2, "Your Trial and Wonder", "", { "<b>Trial of the Elements</b> (your city trial): kill with two or more elements - 20 on Novice up to 60 on Legendary.", "<b>The Staff of Magnus</b> (your wonder): it can't be bought. Once six cities are freed, all four <b>secrets</b> wake - long hidden quests played from altar to altar, never twice in a row in the same city, one at a time (your own class's first). Any class may win and wield any wonder. Listen to the freed altars' whispers. When it is won the Greybeards call: the wonder floats waiting in High Hrothgar's great hall. Hold its beam on the dead to drain them and feed your magicka; where the beam lets go it erupts. Hold it two seconds or more and the eruption leaves an orb of searing light pulsing on everything round it. Hotter still once the three dragons fall." } },
		{ 2, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead are the curse's whole host, each under its own name: Mihail's zombies and the Thriceborn walk first with the Rag Draugr, rotten skeletons and plague wolves; then Bonemen, skeleton mages and the necromancers who serve the curse; then Hulking Draugr, Draugr Liches, Draman Brutes, Ash Spawn and werewolves; then the Daedra - Clannfear, Daedroth, Dremora - and at the last the Overlords, the Mythic Liches and the Skeleton Reaper Warlords. Casters keep back and raise more dead - kill them first.", "Some nights the noise you make draws a hunter: a feral nightwalker, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars and the Tablet of Mysteries. After night 10, as the dead grow many, each kill gives a little less. From dusk to dawn a lantern at your belt lights 20 metres round you. At dawn the dead leave their ash where they fell, and in a freed city its people leave an offering at their altar for you each day.", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 2, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for Cursed Essence - each class keeps its own kit and progress), then sections that open one at a time: <b>Your Kit</b> (select an item to upgrade it), <b>the Armory</b> (new items, opened by freed cities), <b>Perks</b>, <b>Your Dragon</b>, the city's <b>Trials</b> and the <b>Whispers</b> of your path's secret.", "<b>Brews</b> (the Perks section): the seven every class can take - <b>Troll's Hide Mead</b> +50 health; <b>Wellspring Draught</b> +50 magicka; <b>Stormrunner Brew</b> you move 15% faster; <b>Bounty Hunter's Ale</b> elites and mini-bosses give twice the Cursed Essence; <b>Last Stand Ale</b> below a quarter of your health you take 25% less; <b>Gilded Tongue Tonic</b> 15% more Cursed Essence from kills; <b>Dragonsblood Cider</b> your shouts recharge 25% faster - and three of your class's own. Up to five at once, 3,000 each, kept through death; select one you hold to give it back for half.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. Its fall ends the night and drops 3,000 Cursed Essence. A freed city is a sanctuary: none of the curse's dead rise inside it. Whiterun gives you a dragon to ride and Dragon's Updraft; Solitude gives you the Dance of Death.", "<b>Every 5th night</b> a great boss walks with the dead - kill it before dawn.", "<b>Waking an altar</b>: Riverwood's altar is open from the first night. Every other city's trials stay locked until that city's own quest is done - Whiterun: <b>Dragon Rising</b>; Solitude: <b>The Wolf Queen Awakened</b>; Windhelm: <b>The White Phial</b>; Markarth: <b>The Forsworn Conspiracy</b>; Riften: <b>The Book of Love</b>; Falkreath: <b>Ill Met By Moonlight</b>; Morthal: <b>Laid to Rest</b>; Dawnstar: <b>Waking Nightmare</b>; Winterhold: the Jarl's <b>Helm of Winterhold</b> (Dungeon Delving)." } },
		{ 2, "The Tablet of Mysteries", "", { "Once a city is freed, an old floating tablet of cracked stone waits in one of the freed cities - on your map and compass. Pay Cursed Essence and it turns: its rings grind round and a <b>donated weapon</b> rises out of its face. Activate the tablet within 12 seconds to take it: it goes straight into your hands (what you held goes back to your pack).", "<b>Price</b>: 1,500 a turn, and 500 more after every turn or repair, back to 1,500 at dawn; after night 10 it is 3% higher each night.", "<b>Used and forgotten</b>: a <b>worn</b> weapon is one tier above your class sword; a <b>battered</b> one (15% of turns - the tablet rings gold) is two tiers above, with fewer uses. Each has limited uses - hits, arrows or casts - shown in its name (62%) and on a bar under your hand cards. Holding it at the tablet, pay a turn's price to <b>mend</b> it to full. At nothing left it breaks; fall and it is lost. You carry one at a time: a new one replaces it.", "<b>The mask</b>: after four to eight turns a Dragon Priest's mask may rise instead - your Cursed Essence comes back and the tablet flies to another freed city. In a party each player turns their own.", "<b>Worn</b>: <b>Stormtalons</b> (claws, 100 uses) - every 3rd hit jumps lightning to 2 more of the dead; a heavy hit stuns the one struck. <b>Gravebell Mace</b> (mace, 100 uses) - every 5th hit tolls it, stunning the dead within 5 m. <b>Riverstone Halberd</b> (halberd, 100 uses) - its hits knock the dead back; a heavy attack splits the ground in a line before you. <b>Rimewick Quarterstaff</b> (quarterstaff, 100 uses) - its spins strike like any staff's; a heavy attack that lands throws the light out as an orb that pulls the dead in, then bursts. <b>Cinderclaws</b> (claws, 100 uses) - every swipe sets the dead burning; a heavy swipe flings a fan of embers. <b>Frostmourn Rapier</b> (rapier, 100 uses) - its thrusts slow everything they touch; a heavy thrust freezes a ring of the dead around you. <b>Silver Reaping Scythe</b> (scythe, 100 uses) - every hit on the dead strikes a quarter harder. <b>Wyrmtooth Scythe</b> (scythe, 100 uses) - its hits make the dead bleed; a heavy sweep bursts teeth out of the ground in an arc ahead.", "<b>Battered</b>: <b>Talons of Woe</b> (claws, 30 uses) - their bleed runs twice as deep in the dead, and each kill heals you a little. <b>Wyrmspine Pike</b> (pike, 30 uses) - its thrusts pierce through 2 more of the dead in a line; a heavy thrust drives a spike of bone up out of the ground ahead. <b>Eclipse Edge</b> (glass pike, 30 uses) - light thrusts alternate the two; a heavy attack calls a 6-second eclipse that blinds and slows the dead. <b>The Wandering Star</b> (wand, 30 uses) - hold its cast and it looses a star every half second, bouncing on through two more of the dead. <b>Bonereaper</b> (scythe, 30 uses) - one kill in four raises the fallen to fight for you for 20 seconds. <b>Bloodmoon Scythe</b> (scythe, 30 uses) - every hit drains a little of the dead's blood into you; a heavy sweep drains everything it touches." } },
		{ 2, "The Road to the Echo", "", { "<b>High Hrothgar's hall</b>: once six cities are free, the four <b>secrets</b> wake - your own class's first, then the others, one at a time. Win one and the Greybeards call you - its <b>wonder</b> floats waiting in High Hrothgar's great hall. Look at it and press Activate or left click to take it up. Every wonder answers to every class: mix and match.", "<b>The three dragons</b>: with all four wonders won (win each secret in turn, or pool them with your party), Alduin's three words wake as dragons - <b>SLEN</b> at the cult's shrine in the Reach, <b>TIID</b> at Labyrinthian, <b>VO</b> on Mount Anthor. Go at night: the dead come first, then the dragon. Each one slain gives a lasting power, and with all three dead your wonders take their <b>Legendary</b> form.", "<b>The Echo of Alduin</b>: last of all, once the three dragons are dead and every Echo Altar is awake, on the summit of the Throat of the World. Slay it and the curse is broken - the nights are only nights again, and High Hrothgar becomes the <b>Hall of the Awakened</b>: Alduin's Bane floats over the fire at the hall's end, and the <b>Endless Flame</b> burning on the centre pillar holds the rest - the First Dragonborn's Regalia, Alduin's Bones for your dragon, the Endless Night and Begin Again (New Game+)." } },
		{ 2, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay) and changes everything - the dead, the elites, the bosses, and your weapons and spells. Novice is very easy, Apprentice normal, Adept hard, Expert very hard, Master extremely hard and Legendary nearly impossible. From Novice to Legendary the dead have <b>0.6x, 1x, 1.4x, 1.9x, 2.6x, 3.5x</b> health and hit <b>0.5x, 1x, 1.4x, 1.9x, 2.6x, 3.5x</b> as hard, and your weapons and spells deal <b>1.5x, 1x, 0.9x, 0.8x, 0.7x, 0.6x</b> damage.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 3, "The Alchemist", "", { "A wandering <b>alchemist</b>: flasks of fire, frost, storm, acid, holy water and the void, lobbed into the dead - every flask bursts where it lands, on a body, a wall or the ground.", "<b>You start with</b> the <b>Shadowflame Scythe</b> (two-handed - its sweeps set the dead burning with <b>Shadowflame</b>, fire at twice its damage for 5 s; at Tier III the dead that die burning explode and set those round them alight; it grows Forsworn, Falmer, Dwarven, Glass, then Dragon Priest when Ascended), the <b>Fire Flask</b> (sheathe the scythe and your flasks come to hand - attack to throw them, underhand; sheathe the flasks and the scythe comes back) and the <b>Alchemist Set</b> - your armor set (the Gondorian Ranger's cuirass and boots and the Ithilien hood; from Tier I an aura in your class's colour, brighter each tier): Tier I you throw 15% faster, Tier II their bursts reach 20% wider, Tier III each flask kill heals you 2%.", "An Alchemist in your party lets everyone mend slowly in a fight." } },
		{ 3, "Your Progress", "@progress", {  } },
		{ 3, "Your Altar", "", { "<b>Your kit</b> - your sword and each flask with its tier and the price of its next upgrade.", "<b>The Armory</b> - more flasks as you free cities: the <b>Frost Flask</b> at 2, the <b>Shock Flask</b> at 4, the <b>Acid Flask</b> at 6, <b>Holy Water</b> at 8 (the dead burn in it), the <b>Voidglass Flask</b> at 9 (what it drains comes back to you).", "<b>Dragon Priests</b> - every Dragon Priest you slay drops <b>3,000 Cursed Essence</b>." } },
		{ 3, "Getting Stronger", "", { "<b>One curve for everything.</b> Every item in your kit climbs Base, <b>Tier I</b> (1.3 times its damage), <b>Tier II</b> (1.7 times), <b>Tier III - Legendary</b> (2.2 times), then <b>Ascends</b> (+0.3 times each). Prices: Tier I 4,000, Tier II 6,000 (needs 2 freed cities), Tier III 8,000 (4 cities), Ascend 10,000 and 2,000 more each time (6 cities); after night 10 every upgrade and Armory price is 3% higher each night. Your class's <b>armor set</b> is in your kit too: it starts at 5% damage reduction and every tier adds 5% (20% at Tier III), with a power of its own at each tier; each Ascend of the set adds 5% to all your damage. As the set climbs it wraps you in an <b>aura</b> of your class's colour: a faint sheen at Tier I, wisps rising off you at Tier II, a full aura at Tier III, burning brighter with each Ascend.", "Every flask bursts in its element where it lands and leaves a pool of it on the ground. <b>Tier I</b> the burst is half again as wide, <b>Tier II</b> a chain reaction - the dead it kills burst in its element too, <b>Tier III - Legendary</b> a cyclone of its element rises where it breaks and rolls into the dead; Ascends add damage. Flasks cost nothing and never run out - only a breath between throws." } },
		{ 3, "Your Perks", "", { "<b>Volatile Tincture</b> - your flasks' bursts reach 25% wider.", "<b>Quickhand Elixir</b> - you throw your flasks 25% faster.", "<b>Catalyst Philter</b> - the dead your flasks hit take 15% more damage for 5 seconds.", "Up to <b>five brews</b> at once, 3,000 each. They stay through death; select one you hold at the altar to give it back for half. Your class's brews work only while you play this class (they still count toward the five); the seven brews every class can take are in <i>The Echo Altar</i>." } },
		{ 3, "Your Trial and Wonder", "", { "<b>Trial of the Crucible</b> (your city trial): kills with your flasks - 10 on Novice up to 30 on Legendary.", "<b>The Mutagen Staff</b> (your wonder): it can't be bought. Once six cities are freed, all four <b>secrets</b> wake - long hidden quests played from altar to altar, never twice in a row in the same city, one at a time (your own class's first). Any class may win and wield any wonder. Listen to the freed altars' whispers. When it is won the Greybeards call: the wonder floats waiting in High Hrothgar's great hall. Its orb is fed by six vials of the elements: hold attack to loose a beam that pierces the dead, pouring each vial in turn for 5 seconds; let go and the emptied vials refill." } },
		{ 3, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead are the curse's whole host, each under its own name: Mihail's zombies and the Thriceborn walk first with the Rag Draugr, rotten skeletons and plague wolves; then Bonemen, skeleton mages and the necromancers who serve the curse; then Hulking Draugr, Draugr Liches, Draman Brutes, Ash Spawn and werewolves; then the Daedra - Clannfear, Daedroth, Dremora - and at the last the Overlords, the Mythic Liches and the Skeleton Reaper Warlords. Casters keep back and raise more dead - kill them first.", "Some nights the noise you make draws a hunter: a feral nightwalker, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars and the Tablet of Mysteries. After night 10, as the dead grow many, each kill gives a little less. From dusk to dawn a lantern at your belt lights 20 metres round you. At dawn the dead leave their ash where they fell, and in a freed city its people leave an offering at their altar for you each day.", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 3, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for Cursed Essence - each class keeps its own kit and progress), then sections that open one at a time: <b>Your Kit</b> (select an item to upgrade it), <b>the Armory</b> (new items, opened by freed cities), <b>Perks</b>, <b>Your Dragon</b>, the city's <b>Trials</b> and the <b>Whispers</b> of your path's secret.", "<b>Brews</b> (the Perks section): the seven every class can take - <b>Troll's Hide Mead</b> +50 health; <b>Wellspring Draught</b> +50 magicka; <b>Stormrunner Brew</b> you move 15% faster; <b>Bounty Hunter's Ale</b> elites and mini-bosses give twice the Cursed Essence; <b>Last Stand Ale</b> below a quarter of your health you take 25% less; <b>Gilded Tongue Tonic</b> 15% more Cursed Essence from kills; <b>Dragonsblood Cider</b> your shouts recharge 25% faster - and three of your class's own. Up to five at once, 3,000 each, kept through death; select one you hold to give it back for half.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. Its fall ends the night and drops 3,000 Cursed Essence. A freed city is a sanctuary: none of the curse's dead rise inside it. Whiterun gives you a dragon to ride and Dragon's Updraft; Solitude gives you the Dance of Death.", "<b>Every 5th night</b> a great boss walks with the dead - kill it before dawn.", "<b>Waking an altar</b>: Riverwood's altar is open from the first night. Every other city's trials stay locked until that city's own quest is done - Whiterun: <b>Dragon Rising</b>; Solitude: <b>The Wolf Queen Awakened</b>; Windhelm: <b>The White Phial</b>; Markarth: <b>The Forsworn Conspiracy</b>; Riften: <b>The Book of Love</b>; Falkreath: <b>Ill Met By Moonlight</b>; Morthal: <b>Laid to Rest</b>; Dawnstar: <b>Waking Nightmare</b>; Winterhold: the Jarl's <b>Helm of Winterhold</b> (Dungeon Delving)." } },
		{ 3, "The Tablet of Mysteries", "", { "Once a city is freed, an old floating tablet of cracked stone waits in one of the freed cities - on your map and compass. Pay Cursed Essence and it turns: its rings grind round and a <b>donated weapon</b> rises out of its face. Activate the tablet within 12 seconds to take it: it goes straight into your hands (what you held goes back to your pack).", "<b>Price</b>: 1,500 a turn, and 500 more after every turn or repair, back to 1,500 at dawn; after night 10 it is 3% higher each night.", "<b>Used and forgotten</b>: a <b>worn</b> weapon is one tier above your class sword; a <b>battered</b> one (15% of turns - the tablet rings gold) is two tiers above, with fewer uses. Each has limited uses - hits, arrows or casts - shown in its name (62%) and on a bar under your hand cards. Holding it at the tablet, pay a turn's price to <b>mend</b> it to full. At nothing left it breaks; fall and it is lost. You carry one at a time: a new one replaces it.", "<b>The mask</b>: after four to eight turns a Dragon Priest's mask may rise instead - your Cursed Essence comes back and the tablet flies to another freed city. In a party each player turns their own.", "<b>Worn</b>: <b>Stormtalons</b> (claws, 100 uses) - every 3rd hit jumps lightning to 2 more of the dead; a heavy hit stuns the one struck. <b>Gravebell Mace</b> (mace, 100 uses) - every 5th hit tolls it, stunning the dead within 5 m. <b>Riverstone Halberd</b> (halberd, 100 uses) - its hits knock the dead back; a heavy attack splits the ground in a line before you. <b>Rimewick Quarterstaff</b> (quarterstaff, 100 uses) - its spins strike like any staff's; a heavy attack that lands throws the light out as an orb that pulls the dead in, then bursts. <b>Cinderclaws</b> (claws, 100 uses) - every swipe sets the dead burning; a heavy swipe flings a fan of embers. <b>Frostmourn Rapier</b> (rapier, 100 uses) - its thrusts slow everything they touch; a heavy thrust freezes a ring of the dead around you. <b>Silver Reaping Scythe</b> (scythe, 100 uses) - every hit on the dead strikes a quarter harder. <b>Wyrmtooth Scythe</b> (scythe, 100 uses) - its hits make the dead bleed; a heavy sweep bursts teeth out of the ground in an arc ahead.", "<b>Battered</b>: <b>Talons of Woe</b> (claws, 30 uses) - their bleed runs twice as deep in the dead, and each kill heals you a little. <b>Wyrmspine Pike</b> (pike, 30 uses) - its thrusts pierce through 2 more of the dead in a line; a heavy thrust drives a spike of bone up out of the ground ahead. <b>Eclipse Edge</b> (glass pike, 30 uses) - light thrusts alternate the two; a heavy attack calls a 6-second eclipse that blinds and slows the dead. <b>The Wandering Star</b> (wand, 30 uses) - hold its cast and it looses a star every half second, bouncing on through two more of the dead. <b>Bonereaper</b> (scythe, 30 uses) - one kill in four raises the fallen to fight for you for 20 seconds. <b>Bloodmoon Scythe</b> (scythe, 30 uses) - every hit drains a little of the dead's blood into you; a heavy sweep drains everything it touches." } },
		{ 3, "The Road to the Echo", "", { "<b>High Hrothgar's hall</b>: once six cities are free, the four <b>secrets</b> wake - your own class's first, then the others, one at a time. Win one and the Greybeards call you - its <b>wonder</b> floats waiting in High Hrothgar's great hall. Look at it and press Activate or left click to take it up. Every wonder answers to every class: mix and match.", "<b>The three dragons</b>: with all four wonders won (win each secret in turn, or pool them with your party), Alduin's three words wake as dragons - <b>SLEN</b> at the cult's shrine in the Reach, <b>TIID</b> at Labyrinthian, <b>VO</b> on Mount Anthor. Go at night: the dead come first, then the dragon. Each one slain gives a lasting power, and with all three dead your wonders take their <b>Legendary</b> form.", "<b>The Echo of Alduin</b>: last of all, once the three dragons are dead and every Echo Altar is awake, on the summit of the Throat of the World. Slay it and the curse is broken - the nights are only nights again, and High Hrothgar becomes the <b>Hall of the Awakened</b>: Alduin's Bane floats over the fire at the hall's end, and the <b>Endless Flame</b> burning on the centre pillar holds the rest - the First Dragonborn's Regalia, Alduin's Bones for your dragon, the Endless Night and Begin Again (New Game+)." } },
		{ 3, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay) and changes everything - the dead, the elites, the bosses, and your weapons and spells. Novice is very easy, Apprentice normal, Adept hard, Expert very hard, Master extremely hard and Legendary nearly impossible. From Novice to Legendary the dead have <b>0.6x, 1x, 1.4x, 1.9x, 2.6x, 3.5x</b> health and hit <b>0.5x, 1x, 1.4x, 1.9x, 2.6x, 3.5x</b> as hard, and your weapons and spells deal <b>1.5x, 1x, 0.9x, 0.8x, 0.7x, 0.6x</b> damage.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 4, "The Spellsword", "", { "A <b>Vigilant of Stendarr</b>: steel in one hand, a touch spell in the other - fire, frost, shock, sun or arcane - that rides every blow of the blade.", "<b>You start with</b> the <b>Spellbound Rapier</b> (its element is the spell in your other hand; at Tier III its arcs carry that spell), <b>Burning Touch</b> (left hand) and the <b>Spellsword Set</b> (Black Mage Armor's Black Archmage plate: cuirass, helm, gauntlets and sabatons) (your armor set): Tier I you mend in a fight, Tier II your blade's hits put magicka back, Tier III your blade hits 15% harder. No shields: your off hand is always a spell, and every blade hit casts it." } },
		{ 4, "Your Progress", "@progress", {  } },
		{ 4, "Your Altar", "", { "<b>Your kit</b> - the blade and each spell with its tier and the price of its next upgrade.", "<b>The Armory</b> - more touch spells open as you free cities: Frost touch at 1, Shock touch at 3, Sun touch at 5, Arcane touch at 7.", "<b>Dragon Priests</b> - every Dragon Priest you slay drops <b>3,000 Cursed Essence</b>." } },
		{ 4, "Getting Stronger", "", { "<b>One curve for everything.</b> Every item in your kit climbs Base, <b>Tier I</b> (1.3 times its damage), <b>Tier II</b> (1.7 times), <b>Tier III - Legendary</b> (2.2 times), then <b>Ascends</b> (+0.3 times each). Prices: Tier I 4,000, Tier II 6,000 (needs 2 freed cities), Tier III 8,000 (4 cities), Ascend 10,000 and 2,000 more each time (6 cities); after night 10 every upgrade and Armory price is 3% higher each night. Your class's <b>armor set</b> is in your kit too: it starts at 5% damage reduction and every tier adds 5% (20% at Tier III), with a power of its own at each tier; each Ascend of the set adds 5% to all your damage. As the set climbs it wraps you in an <b>aura</b> of your class's colour: a faint sheen at Tier I, wisps rising off you at Tier II, a full aura at Tier III, burning brighter with each Ascend." } },
		{ 4, "Your Perks", "", { "<b>Bladesong Mead</b> - each blade hit heals you 5% of your maximum health.", "<b>Spellbinder's Draught</b> - the spell carried on your blade hits 25% harder.", "<b>Spellguard Ale</b> - blocking costs no stamina.", "Up to <b>five brews</b> at once, 3,000 each. They stay through death; select one you hold at the altar to give it back for half. Your class's brews work only while you play this class (they still count toward the five); the seven brews every class can take are in <i>The Echo Altar</i>." } },
		{ 4, "Your Trial and Wonder", "", { "<b>Trial of Steel</b> (your city trial): melee kills with a spell in your other hand - 10 on Novice up to 30 on Legendary.", "<b>Dragon Slayer</b> (your wonder): it can't be bought. Once six cities are freed, all four <b>secrets</b> wake - long hidden quests played from altar to altar, never twice in a row in the same city, one at a time (your own class's first). Any class may win and wield any wonder. Listen to the freed altars' whispers. When it is won the Greybeards call: the wonder floats waiting in High Hrothgar's great hall. It stands two tiers above your blade, and every hit carries the last Spellsword spell you held; once the three dragons fall it grows stronger again, and power attacks loose that spell on the dead round you." } },
		{ 4, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead are the curse's whole host, each under its own name: Mihail's zombies and the Thriceborn walk first with the Rag Draugr, rotten skeletons and plague wolves; then Bonemen, skeleton mages and the necromancers who serve the curse; then Hulking Draugr, Draugr Liches, Draman Brutes, Ash Spawn and werewolves; then the Daedra - Clannfear, Daedroth, Dremora - and at the last the Overlords, the Mythic Liches and the Skeleton Reaper Warlords. Casters keep back and raise more dead - kill them first.", "Some nights the noise you make draws a hunter: a feral nightwalker, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars and the Tablet of Mysteries. After night 10, as the dead grow many, each kill gives a little less. From dusk to dawn a lantern at your belt lights 20 metres round you. At dawn the dead leave their ash where they fell, and in a freed city its people leave an offering at their altar for you each day.", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 4, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for Cursed Essence - each class keeps its own kit and progress), then sections that open one at a time: <b>Your Kit</b> (select an item to upgrade it), <b>the Armory</b> (new items, opened by freed cities), <b>Perks</b>, <b>Your Dragon</b>, the city's <b>Trials</b> and the <b>Whispers</b> of your path's secret.", "<b>Brews</b> (the Perks section): the seven every class can take - <b>Troll's Hide Mead</b> +50 health; <b>Wellspring Draught</b> +50 magicka; <b>Stormrunner Brew</b> you move 15% faster; <b>Bounty Hunter's Ale</b> elites and mini-bosses give twice the Cursed Essence; <b>Last Stand Ale</b> below a quarter of your health you take 25% less; <b>Gilded Tongue Tonic</b> 15% more Cursed Essence from kills; <b>Dragonsblood Cider</b> your shouts recharge 25% faster - and three of your class's own. Up to five at once, 3,000 each, kept through death; select one you hold to give it back for half.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. Its fall ends the night and drops 3,000 Cursed Essence. A freed city is a sanctuary: none of the curse's dead rise inside it. Whiterun gives you a dragon to ride and Dragon's Updraft; Solitude gives you the Dance of Death.", "<b>Every 5th night</b> a great boss walks with the dead - kill it before dawn.", "<b>Waking an altar</b>: Riverwood's altar is open from the first night. Every other city's trials stay locked until that city's own quest is done - Whiterun: <b>Dragon Rising</b>; Solitude: <b>The Wolf Queen Awakened</b>; Windhelm: <b>The White Phial</b>; Markarth: <b>The Forsworn Conspiracy</b>; Riften: <b>The Book of Love</b>; Falkreath: <b>Ill Met By Moonlight</b>; Morthal: <b>Laid to Rest</b>; Dawnstar: <b>Waking Nightmare</b>; Winterhold: the Jarl's <b>Helm of Winterhold</b> (Dungeon Delving)." } },
		{ 4, "The Tablet of Mysteries", "", { "Once a city is freed, an old floating tablet of cracked stone waits in one of the freed cities - on your map and compass. Pay Cursed Essence and it turns: its rings grind round and a <b>donated weapon</b> rises out of its face. Activate the tablet within 12 seconds to take it: it goes straight into your hands (what you held goes back to your pack).", "<b>Price</b>: 1,500 a turn, and 500 more after every turn or repair, back to 1,500 at dawn; after night 10 it is 3% higher each night.", "<b>Used and forgotten</b>: a <b>worn</b> weapon is one tier above your class sword; a <b>battered</b> one (15% of turns - the tablet rings gold) is two tiers above, with fewer uses. Each has limited uses - hits, arrows or casts - shown in its name (62%) and on a bar under your hand cards. Holding it at the tablet, pay a turn's price to <b>mend</b> it to full. At nothing left it breaks; fall and it is lost. You carry one at a time: a new one replaces it.", "<b>The mask</b>: after four to eight turns a Dragon Priest's mask may rise instead - your Cursed Essence comes back and the tablet flies to another freed city. In a party each player turns their own.", "<b>Worn</b>: <b>Stormtalons</b> (claws, 100 uses) - every 3rd hit jumps lightning to 2 more of the dead; a heavy hit stuns the one struck. <b>Gravebell Mace</b> (mace, 100 uses) - every 5th hit tolls it, stunning the dead within 5 m. <b>Riverstone Halberd</b> (halberd, 100 uses) - its hits knock the dead back; a heavy attack splits the ground in a line before you. <b>Rimewick Quarterstaff</b> (quarterstaff, 100 uses) - its spins strike like any staff's; a heavy attack that lands throws the light out as an orb that pulls the dead in, then bursts. <b>Cinderclaws</b> (claws, 100 uses) - every swipe sets the dead burning; a heavy swipe flings a fan of embers. <b>Frostmourn Rapier</b> (rapier, 100 uses) - its thrusts slow everything they touch; a heavy thrust freezes a ring of the dead around you. <b>Silver Reaping Scythe</b> (scythe, 100 uses) - every hit on the dead strikes a quarter harder. <b>Wyrmtooth Scythe</b> (scythe, 100 uses) - its hits make the dead bleed; a heavy sweep bursts teeth out of the ground in an arc ahead.", "<b>Battered</b>: <b>Talons of Woe</b> (claws, 30 uses) - their bleed runs twice as deep in the dead, and each kill heals you a little. <b>Wyrmspine Pike</b> (pike, 30 uses) - its thrusts pierce through 2 more of the dead in a line; a heavy thrust drives a spike of bone up out of the ground ahead. <b>Eclipse Edge</b> (glass pike, 30 uses) - light thrusts alternate the two; a heavy attack calls a 6-second eclipse that blinds and slows the dead. <b>The Wandering Star</b> (wand, 30 uses) - hold its cast and it looses a star every half second, bouncing on through two more of the dead. <b>Bonereaper</b> (scythe, 30 uses) - one kill in four raises the fallen to fight for you for 20 seconds. <b>Bloodmoon Scythe</b> (scythe, 30 uses) - every hit drains a little of the dead's blood into you; a heavy sweep drains everything it touches." } },
		{ 4, "The Road to the Echo", "", { "<b>High Hrothgar's hall</b>: once six cities are free, the four <b>secrets</b> wake - your own class's first, then the others, one at a time. Win one and the Greybeards call you - its <b>wonder</b> floats waiting in High Hrothgar's great hall. Look at it and press Activate or left click to take it up. Every wonder answers to every class: mix and match.", "<b>The three dragons</b>: with all four wonders won (win each secret in turn, or pool them with your party), Alduin's three words wake as dragons - <b>SLEN</b> at the cult's shrine in the Reach, <b>TIID</b> at Labyrinthian, <b>VO</b> on Mount Anthor. Go at night: the dead come first, then the dragon. Each one slain gives a lasting power, and with all three dead your wonders take their <b>Legendary</b> form.", "<b>The Echo of Alduin</b>: last of all, once the three dragons are dead and every Echo Altar is awake, on the summit of the Throat of the World. Slay it and the curse is broken - the nights are only nights again, and High Hrothgar becomes the <b>Hall of the Awakened</b>: Alduin's Bane floats over the fire at the hall's end, and the <b>Endless Flame</b> burning on the centre pillar holds the rest - the First Dragonborn's Regalia, Alduin's Bones for your dragon, the Endless Night and Begin Again (New Game+)." } },
		{ 4, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay) and changes everything - the dead, the elites, the bosses, and your weapons and spells. Novice is very easy, Apprentice normal, Adept hard, Expert very hard, Master extremely hard and Legendary nearly impossible. From Novice to Legendary the dead have <b>0.6x, 1x, 1.4x, 1.9x, 2.6x, 3.5x</b> health and hit <b>0.5x, 1x, 1.4x, 1.9x, 2.6x, 3.5x</b> as hard, and your weapons and spells deal <b>1.5x, 1x, 0.9x, 0.8x, 0.7x, 0.6x</b> damage.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 5, "The Broken Words: Riverwood", "", { "<i>We raised this altar in the valley where the river runs out of the mountains, and cut the valley's words into its heart-stone. Vahlok, the cult's jailor, watched us do it from the barrow on the peak. He swore to Alduin that no prisoner of his would ever go free - and the dead, to him, are prisoners.</i>", "The Dragon Priest of Riverwood: <b>Vahlok the Jailor</b>. Vahlok kept the cult's prisoners in the Merethic Era, and his oath to Alduin was the last he swore. It has brought him out of his tomb and across the sea to the barrow above Riverwood, to keep the valley's altar dark.", "The words on the heart-stone: <b>STRUN BAH QO</b> ('Storm Wrath Lightning') - <i>Thunder Lash</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 6, "The Broken Words: Whiterun", "", { "<i>The plains' altar is the one Nahkriin hates most, for it stands nearest the road to Sovngarde. He kept that road for Alduin at Skuldafn. When the World-Eater's mist lies on the door, Nahkriin will come to the plains to keep it there.</i>", "The Dragon Priest of Whiterun: <b>Nahkriin, Warden of Skuldafn</b>. Nahkriin guarded Skuldafn, the gate to Sovngarde, for Alduin, and the mist that bars Sovngarde's door is his to keep. He has come down from the mountains to the plains, so that Whiterun's dead never find the way home.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 7, "The Broken Words: Solitude", "", { "<i>Volsung could breathe on the peaks where we could not, and he laughed at our altar under the cliffs of Haafingar. But the Voice carries further than breath. The runes on its heart-stone hold the words that answer him.</i>", "The Dragon Priest of Solitude: <b>Volsung of Volskygge</b>. Volsung ruled the peaks above Haafingar from Volskygge, and his mask let him breathe where no man could. He climbs down to Solitude now, and the dead of the Blue Palace's crypts rise at his word.", "The words on the heart-stone: <b>DIL VAAZ ZOL</b> ('Undead Tear Zombie') - <i>Raise the Fallen</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 8, "The Broken Words: Windhelm", "", { "<i>Zahkriisos was not of this land; he came over the Sea of Ghosts with the cult's fleet, and the cold came with him. We set the altar of the east by the water so that it would hear him first if he ever came back across the ice.</i>", "The Dragon Priest of Windhelm: <b>Zahkriisos the Frost-Priest</b>. Zahkriisos lay in his tomb on Solstheim until Alduin's shout crossed the Sea of Ghosts. He walked over the ice to Windhelm's docks, and the cold he carries stops a heart.", "The words on the heart-stone: <b>IIZ SLEN NUS</b> ('Ice Flesh Statue') - <i>Frost Nova</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 9, "The Broken Words: Markarth", "", { "<i>Even the cult feared Otar. They walled him up in Ragnvald while he still breathed. We did not trust the wall, so we raised an altar on the Reach's stone and cut into it words he could not shout down.</i>", "The Dragon Priest of Markarth: <b>Otar the Mad</b>. Otar was so cruel that his own cult sealed him alive in Ragnvald. His oath to Alduin outlived his reason. He climbs out of the Reach's stone beneath Markarth to guard its altar.", "The words on the heart-stone: <b>GOL VAH DEN</b> ('Earth Spring Hold') - <i>Dwemer Quake</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 10, "The Broken Words: Riften", "", { "<i>Rahgot's people drank poison sooner than see him taken. A priest who can ask that of his followers will ask it again. When he rises, the Rift's dead will come with him, and the altar must be woken to send them back.</i>", "The Dragon Priest of Riften: <b>Rahgot of Forelhost</b>. Rahgot's followers poisoned themselves in Forelhost rather than surrender him to the Tongues. They rise with him now, and the Rift's dead follow them down to Riften's altar.", "The words on the heart-stone: <b>FEIM ZII GRON</b> ('Fade Spirit Bind') - <i>Shadow Step</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 11, "The Broken Words: Falkreath", "", { "<i>Krosis wept for a thousand years at Shearpoint, guarding a word no one came to learn. Grief is a long oath. The altar of the pines is cut with gentler words than the rest - to put children back to sleep.</i>", "The Dragon Priest of Falkreath: <b>Krosis of Shearpoint</b>. Krosis guarded the word at Shearpoint, mourning, for a thousand years. Alduin's shout gave him something to do with his sorrow: he comes down to Falkreath's graveyard to keep its children in the ground no longer.", "The words on the heart-stone: <b>KRII LUN AUS</b> ('Kill Leech Suffer') - <i>Death's Harvest</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 12, "The Broken Words: Morthal", "", { "<i>Hevnoraak's own servants sealed him in Valthume, and set the seal with his blood. No seal holds against SLEN TIID VO. When the marsh fog thickens, look to the altar, and to the words on its heart-stone.</i>", "The Dragon Priest of Morthal: <b>Hevnoraak of Valthume</b>. Hevnoraak's servants sealed him in Valthume to stop him rising. The seal could not hold against SLEN TIID VO: he walks out of the marsh fog, and Hjaalmarch's drowned dead follow him.", "The words on the heart-stone: <b>ZUN HAAL VIIK</b> ('Weapon Hand Defeat') - <i>Mire Grasp</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 13, "The Broken Words: Dawnstar", "", { "<i>Vokun's shadows reached into men's dreams. The priests at the temple on the hill dreamed of him for a thousand years before he came. Wake the altar, and the town will sleep without dreaming of him again.</i>", "The Dragon Priest of Dawnstar: <b>Vokun of High Gate</b>. Vokun was a priest of shadows, and the Nightcaller's dreamers in Dawnstar dreamed his return a thousand years before it came. Kill him, and Dawnstar's nightmares end.", "The words on the heart-stone: <b>FAAS RU MAAR</b> ('Fear Run Terror') - <i>Nightmare Howl</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 14, "The Broken Words: Winterhold", "", { "<i>Morokei held the Staff of Magnus in Bromjunaar, and the mages who came after us have never forgotten him. The northern altar stands on the cliffs where the storms break; its words are cut deepest of all, for he is the strongest of them.</i>", "The Dragon Priest of Winterhold: <b>Morokei of Labyrinthian</b>. Morokei once held the Staff of Magnus in Labyrinthian, and the College has feared him ever since. He has come to the cliffs above Winterhold, and the storm he calls has not finished yet.", "The words on the heart-stone: <b>SU GRAH DUN</b> ('Air Battle Grace') - <i>Arcane Singularity</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
	};
}
